package com.requestmanagement.backend.guestform;

import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.web.servlet.*;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDate;
import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @Transactional
class ProjectGuestFormIntegrationTests {
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc;
 @Test void newProjectHasBackwardCompatibleDefaultsAndPublicFormIsMinimal() throws Exception { Session a=login("sara.saad@example.com");long p=createProject(a,"Form Defaults");mvc.perform(get("/api/guest/projects/{p}/form",p)).andExpect(status().isOk()).andExpect(jsonPath("$.workTypeVisible").value(true)).andExpect(jsonPath("$.priorityRequired").value(true)).andExpect(jsonPath("$.descriptionRequired").value(true)).andExpect(jsonPath("$.defaultWorkTypeId").doesNotExist()).andExpect(jsonPath("$.fields.length()").value(0)); }
 @Test void adminConfiguresHiddenDefaultsAndGuestSubmissionUsesThem() throws Exception {Session a=login("sara.saad@example.com");long p=createProject(a,"Hidden Defaults");long type=jdbc.queryForObject("SELECT work_type_id FROM project_work_types WHERE project_id=? AND work_type_name='Bug'",Long.class,p);mvc.perform(put("/api/projects/{p}/guest-form/settings",p).session(a.session()).cookie(a.csrf()).header("X-XSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{\"workTypeVisible\":false,\"defaultWorkTypeId\":"+type+",\"priorityVisible\":false,\"priorityRequired\":false,\"descriptionVisible\":false,\"descriptionRequired\":false}" )).andExpect(status().isOk());Cookie c=csrf();MvcResult result=mvc.perform(post("/api/guest/requests/projects/{p}",p).cookie(c).header("X-XSRF-TOKEN",c.getValue()).with(r->{r.setRemoteAddr("203.0.113.201");return r;}).contentType("application/json").content("{\"guestName\":\"Guest\",\"guestEmail\":\"guest@example.com\",\"title\":\"Hidden fields\",\"answers\":[]}" )).andExpect(status().isCreated()).andReturn();long id=((Number)com.jayway.jsonpath.JsonPath.read(result.getResponse().getContentAsString(),"$.requestId")).longValue();var row=jdbc.queryForMap("SELECT project_work_type_id,priority,description FROM requests WHERE request_id=?",id);assertThat(((Number)row.get("project_work_type_id")).longValue()).isEqualTo(type);assertThat(row.get("priority")).isEqualTo("MEDIUM");assertThat(row.get("description")).isEqualTo("");}
 @Test void customAnswersValidateAndPreserveSnapshots() throws Exception {Session a=login("sara.saad@example.com");long p=createProject(a,"Snapshots");long work=jdbc.queryForObject("SELECT work_type_id FROM project_work_types WHERE project_id=? LIMIT 1",Long.class,p);long text=createField(a,p,"Asset tag","TEXT",true,"[]");long dropdown=createField(a,p,"Location","DROPDOWN",true,"[\"Riyadh\",\"Jeddah\"]");long option=jdbc.queryForObject("SELECT option_id FROM project_guest_field_options WHERE guest_field_id=? AND option_label='Riyadh'",Long.class,dropdown);Cookie c=csrf();MvcResult result=mvc.perform(post("/api/guest/requests/projects/{p}",p).cookie(c).header("X-XSRF-TOKEN",c.getValue()).with(r->{r.setRemoteAddr("203.0.113.202");return r;}).contentType("application/json").content("{\"guestName\":\"Guest\",\"guestEmail\":\"guest@example.com\",\"title\":\"Dynamic\",\"description\":\"Details\",\"priority\":\"HIGH\",\"workTypeId\":"+work+",\"answers\":[{\"fieldId\":"+text+",\"value\":\"LT-42\"},{\"fieldId\":"+dropdown+",\"value\":\""+option+"\"}]}" )).andExpect(status().isCreated()).andReturn();long request=((Number)com.jayway.jsonpath.JsonPath.read(result.getResponse().getContentAsString(),"$.requestId")).longValue();mvc.perform(put("/api/projects/{p}/guest-form/fields/{f}",p,text).session(a.session()).cookie(a.csrf()).header("X-XSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{\"label\":\"Renamed\",\"type\":\"TEXT\",\"required\":true,\"options\":[]}" )).andExpect(status().isOk());mvc.perform(get("/api/projects/{p}/tasks/{r}",p,request).session(a.session())).andExpect(status().isOk()).andExpect(jsonPath("$.guestAnswers[0].label").value("Asset tag")).andExpect(jsonPath("$.guestAnswers[0].value").value("LT-42")).andExpect(jsonPath("$.guestAnswers[1].optionLabel").value("Riyadh"));mvc.perform(put("/api/projects/{p}/guest-form/fields/{f}",p,text).session(a.session()).cookie(a.csrf()).header("X-XSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{\"label\":\"Changed Type\",\"type\":\"NUMBER\",\"required\":true,\"options\":[]}" )).andExpect(status().isConflict());}
 @Test void pastGuestDatesAreRejectedWithoutPersistingARequest() throws Exception {Session a=login("sara.saad@example.com");long p=createProject(a,"Date Validation");long date=createField(a,p,"Visit date","DATE",true,"[]");long work=jdbc.queryForObject("SELECT work_type_id FROM project_work_types WHERE project_id=? LIMIT 1",Long.class,p);long before=jdbc.queryForObject("SELECT COUNT(*) FROM requests",Long.class);Cookie c=csrf();String past=LocalDate.now(GuestFormSubmissionService.APPLICATION_ZONE).minusDays(1).toString();mvc.perform(post("/api/guest/requests/projects/{p}",p).cookie(c).header("X-XSRF-TOKEN",c.getValue()).with(r->{r.setRemoteAddr("203.0.113.204");return r;}).contentType("application/json").content("{\"guestName\":\"Guest\",\"guestEmail\":\"guest@example.com\",\"title\":\"Past date\",\"description\":\"Details\",\"priority\":\"LOW\",\"workTypeId\":"+work+",\"answers\":[{\"fieldId\":"+date+",\"value\":\""+past+"\"}]}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.message").value("Visit date cannot be in the past."));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM requests",Long.class)).isEqualTo(before);}
 @Test void securityArchiveScopeAndInvalidAnswersAreRejectedAtomically() throws Exception {Session a=login("sara.saad@example.com"),e=login("nora.ahmed@example.com");long p=createProject(a,"Security Form"),other=createProject(a,"Other Form");long foreign=createField(a,other,"Foreign","TEXT",false,"[]");mvc.perform(post("/api/projects/{p}/guest-form/fields",p).session(e.session()).cookie(e.csrf()).header("X-XSRF-TOKEN",e.csrf().getValue()).contentType("application/json").content("{\"label\":\"No\",\"type\":\"TEXT\",\"required\":false,\"options\":[]}" )).andExpect(status().isForbidden());long before=jdbc.queryForObject("SELECT COUNT(*) FROM requests",Long.class);Cookie c=csrf();long work=jdbc.queryForObject("SELECT work_type_id FROM project_work_types WHERE project_id=? LIMIT 1",Long.class,p);mvc.perform(post("/api/guest/requests/projects/{p}",p).cookie(c).header("X-XSRF-TOKEN",c.getValue()).with(r->{r.setRemoteAddr("203.0.113.203");return r;}).contentType("application/json").content("{\"guestName\":\"Guest\",\"guestEmail\":\"guest@example.com\",\"title\":\"Invalid\",\"description\":\"Details\",\"priority\":\"LOW\",\"workTypeId\":"+work+",\"answers\":[{\"fieldId\":"+foreign+",\"value\":\"x\"}]}" )).andExpect(status().isBadRequest());assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM requests",Long.class)).isEqualTo(before);jdbc.update("UPDATE projects SET status='ARCHIVED' WHERE project_id=?",p);mvc.perform(post("/api/projects/{p}/guest-form/fields",p).session(a.session()).cookie(a.csrf()).header("X-XSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{\"label\":\"Archived\",\"type\":\"TEXT\",\"required\":false,\"options\":[]}" )).andExpect(status().isConflict());}
 private long createField(Session a,long p,String label,String type,boolean required,String options)throws Exception{MvcResult r=mvc.perform(post("/api/projects/{p}/guest-form/fields",p).session(a.session()).cookie(a.csrf()).header("X-XSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{\"label\":\""+label+"\",\"type\":\""+type+"\",\"required\":"+required+",\"options\":"+options+"}" )).andExpect(status().isCreated()).andReturn();return ((Number)com.jayway.jsonpath.JsonPath.read(r.getResponse().getContentAsString(),"$.id")).longValue();}
 private long createProject(Session a,String name)throws Exception{MvcResult r=mvc.perform(post("/api/projects").session(a.session()).cookie(a.csrf()).header("X-XSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{\"name\":\""+name+"\",\"description\":null}" )).andExpect(status().isCreated()).andReturn();return ((Number)com.jayway.jsonpath.JsonPath.read(r.getResponse().getContentAsString(),"$.id")).longValue();}
 private Cookie csrf()throws Exception{Cookie c=mvc.perform(get("/api/auth/csrf")).andReturn().getResponse().getCookie("XSRF-TOKEN");assertThat(c).isNotNull();return c;} private Session login(String email)throws Exception{Cookie c=csrf();MvcResult r=mvc.perform(post("/api/auth/login").cookie(c).header("X-XSRF-TOKEN",c.getValue()).contentType("application/json").content("{\"email\":\""+email+"\",\"password\":\"Password123\"}" )).andExpect(status().isOk()).andReturn();return new Session((MockHttpSession)r.getRequest().getSession(false),c);} private record Session(MockHttpSession session,Cookie csrf){}
}
